def pid(x):return x if isinstance(x,str) else f'P{x:03}'
def ids(xs):return list(dict.fromkeys(pid(x) for x in xs))
def ev(refs,mode='现场',infer=False):
 out=[]
 for q in refs:
  r=P[pid(q)]
  if r['episode'] is None:raise ValueError(q)
  out.append({'episode':r['episode'],'scene':r['scene'],'mode':mode,'source_id':r['id'],'inferred':infer})
 return out
def n(sheet,key,name,desc,sources,events=None,parent='',kind='资产',candidate=False,outfit='',planned=None):
 r={'id':key,'name':name,'description':desc,'parent_id':parent,'kind':kind,'source_ids':ids(sources),'events':events or [],'candidate':candidate,'planned_episodes':planned or [],'outfit_id':outfit,'review':'待确认' if candidate else '不适用','user_notes':''}
 data['assets'][sheet].append(r);return r
def role(key,name,desc,sources,events=None):return n('角色',key,name,desc,sources,events)
def variant(parent,suffix,name,desc,sources,events=None,kind='状态',candidate=False,planned=None,outfit=''):
 return n('角色',parent+'-'+suffix,name,desc,sources,events,parent,kind,candidate,outfit,planned)

