for suffix,name,desc in [('01','摆摊老头','身份／外貌：摆摊的老年男性。\n边界：江辰观察的对象，未证实实际身份或手持武器；未写服装。'),('02','扫地清洁工','身份／行为：正在扫地的清洁工。\n边界：未明确年龄、性别、制服和具体工具，不能因职业直接当作原文有某套制服。'),('03','接送家长','身份／功能：校门接送人群中的家长；人数未给出。\n边界：未证实与杀手身份对应，服装与外貌未写。')]:n('角色','R32-'+suffix,name,desc,[436],ev([436]),'R32','成员')
