role('R34','邪修残魂〔仅小传／大纲〕','身份：寄托琉璃灯、隐藏在银女体内并意图夺舍的残魂。\n范围：本轮正文未出场；不把它与银女的身体直接合并成同一角色身份。\n形态：没有可核的独立外观与服装描写。',[12,48,53])

# Spaces are supported by actual headings and pictured action, not inherited 60-episode ranges.
def scene(key,name,desc,refs,events,parent='',kind='母场景'):return n('场景',key,name,desc,refs,events,parent,kind)
scene('S03','国外绑匪基地','功能：营救开场与孤狼身份展示。\n结构：楼顶俯瞰地面活动区，江辰从高处落地；苏小菲被绑在柱子上，随后直升机接应。\n陈设：烧烤架、食物和酒、绑缚柱、手持信号器；确切建筑尺寸未写。\n环境：白天、室外；战斗中基地发生多处爆炸，不能随镜头换基地结构。',[62,64,71,73,74,85,89,90,95,96,108,109],ev([62,71]))
scene('S03-01','楼顶／俯瞰位置','功能：建立江辰观察与入场的高低关系。\n结构：能俯瞰基地并与地面落点衔接；具体栏杆、楼梯或高度未写。\n环境：日外，面具与耳机在此建立；不补出原文没有的屋顶设备。',[62,64,65,85],ev([64]),'S03','子场景')
scene('S03-02','地面绑架／交战区','功能：逼问、营救、徒手战斗和直升机接应。\n结构：烧烤活动区与绑架柱相邻，绑匪可形成包围圈，江辰能由高处落地。\n陈设：烧烤架、食物、酒、柱子；直升机落地关系需与同一地面空间一致。',[71,73,74,75,85,89,90,95,102,108],ev([73]),'S03','子场景')
scene('S03-02-01','爆炸／火光状态','变化：同一基地突然多处爆炸、火光冲天。\n边界：原文没有明确具体倒塌建筑、碎片规模或爆炸装置，不能自行当作已写出的物理毁坏。',[95,96,97,98],ev([96]),'S03-02','状态')
scene('S08','咖啡馆','功能：确定保镖关系、日常喜剧冲突及路人采访。\n结构：室内沙发座区与门口采访区连续，江辰跟随苏小菲走出。\n陈设：室内对坐沙发；门口有拍摄装备、广告牌、测谎仪及围观路人。\n环境：白天；内外立面、出口方向需统一。',[119,120,121,136,152,155,157,158,159,169,171,180,181,182,195,201,202],ev([119,157,180]))
scene('S08-01','室内沙发座区','功能：父女谈话、江辰报到及确定保镖。\n结构：苏向南与苏小菲对坐沙发，江辰从门口进入再跟出；其他座位布局未写。\n陈设：沙发、苏小菲手机和棒棒糖；不凭咖啡馆名称补写特定杯具镜头。',[119,121,126,136,148,149,152,155],ev([121]),'S08','子场景')
scene('S08-02','门口采访区','功能：围观者质疑与测谎反转。\n结构：与店门、保姆车上下车位置衔接，可容女主播和五名路人。\n陈设：拍摄装备、寻找路人英雄广告牌、测谎仪；均有明确叙事用途，非普通固定家具。',[157,158,159,162,169,171,180,182,195,201,202,203,204],ev([159,182]),'S08','子场景')
scene('S01','苏家别墅','功能：入住、日常相处、夜袭、卧室追查和次晨遮掩事件。\n结构：公共室内、楼梯、苏小菲卧室与阳台、院子、早餐餐桌区；卧室阳台可看院子。\n陈设：沙发、床与被子、窗、餐桌与饭碗餐具；院子有围墙、花坛、水池、台阶。\n环境：第3集白天，第6—7集夜晚，第8集夜间承接及白天；不把未来订婚布置算进本轮。',[206,208,211,219,317,319,322,323,325,329,331,336,344,346,348,353,357,370,372,374,378,382,388,392,394,396,397,399,400,407,414],ev([208,319,346,396]))
scene('S01-01','公共室内／沙发区','功能：入住逗藏獒、夜归、发现潜入。\n结构：有沙发、上楼路线与可观察窗外的位置；第3与第6集是否完全同一区未明确，先作为公共室内制作需求整合。\n陈设：沙发、饮水位置；不要把未写的家具数量和方向锁死。',[206,208,211,214,219,317,319,321,322,323,325,327],ev([211,319]),'S01','子场景')
scene('S01-01-01','白天入住状态','环境：第3集日内，藏獒在沙发旁，苏家父女带江辰入住。\n连续性：保留公共室内与楼梯/出入口关系；原文未给具体光位。',[206,208,211,214,219],ev([211]),'S01-01','状态')
scene('S01-01-02','深夜归家状态','环境：第6集夜内，购物袋被放下，苏小菲上楼，江辰饮水并看窗外。\n布局边界：此区与第3集沙发区是否同处属制作整合待核，不在原文中伪写相同机位。',[317,319,321,322,323,325,327],ev([319]),'S01-01','状态')
scene('S01-06','楼梯／上下楼连接','功能：连接公共室内与苏小菲楼上卧室。\n证据：第6集上楼，第8集穿睡衣冲下楼。\n设计缺口：楼梯具体形式、拐角、宽度及扶手未写，应与母场景一致设计。',[322,392,397],ev([322,397]),'S01','子场景')
scene('S01-10','苏小菲卧室','功能：发现夜战、被抱回床、江辰追查玉、次晨醒来。\n结构：床、窗边及可通往阳台的动线；卧室位于楼上。\n陈设：床、被子、窗；原文未写柜体、灯具和具体朝向。\n服装关联：苏小菲睡衣及扣子结构在此需要保持。',[344,346,348,370,372,373,374,376,378,379,382,384,385,386,388,390,392,397],ev([346,372,384,390]),'S01','子场景')
scene('S01-10-01','卧室阳台','功能：苏小菲从卧室走出，俯见院子中匕首刺向江辰。\n空间关系：阳台与卧室相通，能看清院子战斗；栏杆形式和具体高度未写。\n连续性：俯瞰方向必须与院内人物位置对应。',[344,346,348,349,350,351],ev([348]),'S01-10','子场景')
scene('S01-10-02','夜间卧床／追查状态','环境：第7集夜间到第8集夜间承接。\n陈设与动作：苏小菲被放在床上，江辰到窗边通话，再回床边观察衣领；不改变床窗关系。',[370,372,373,374,376,378,379,382,384,385,386],ev([372,384]),'S01-10','状态')
scene('S01-10-03','次晨起床状态','环境：第8集日内，苏小菲掀被起床，未换睡衣冲出。\n连续性：仍为同一床、被子、卧室与下楼路线，不另换房间。',[388,389,390,391,392,397],ev([390]),'S01-10','状态')
scene('S01-08','院子','功能：夜袭战斗、阳台观察与次晨清理反转。\n结构：围墙可翻越，院子连别墅入口；花坛、水池、台阶和可撞击的墙构成落点。\n陈设：原文明确这些固定部件，但未写尺寸和精确位置。',[329,330,331,332,336,344,348,353,355,356,357,368,394,407,408],ev([331,348,357,407]),'S01','子场景')
scene('S01-08-02','夜袭／倒地人员状态','环境：第6—7集同一夜；打手翻墙，落入花坛、水池或台阶，后横七竖八躺在院中。\n连续性：落点、墙与阳台视线需衔接；不擅自认定所有景物都损坏。',[329,331,336,344,348,353,356,357],ev([331,357]),'S01-08','状态')
scene('S01-08-01','次晨整洁状态','变化：第8集院子整洁，看不到打斗痕迹。\n叙事功能：对比夜袭结果，使苏小菲怀疑自己做梦。\n边界：清理过程没有在正文出现，不另加清理工出镜。',[375,394,407,408],ev([407]),'S01-08','状态')
scene('S01-02','早餐餐桌区','功能：次晨对质与掩饰夜袭。\n结构：位于别墅公共室内，可由楼梯到达，并与院子视线/出入口衔接。\n陈设：餐桌、饭碗、餐具；具体装饰、早餐种类未写。',[394,395,396,397,398,399,400,407,414],ev([396]),'S01','子场景')
scene('S09','商场／公共活动区','功能：张阎王围堵、江辰隐藏实力反击、无人机威慑。\n结构：日内公共购物活动区，可容主角与五名手下；不远处空中能悬停无人机。\n陈设：原文未给店面品牌、楼层、柜台和通道精确结构；不照搬其他项目商场。\n连续性：第3—5集是同一冲突连续段，无人机位置与动作方向需衔接。',[227,228,229,230,255,256,264,265,266,267,276,277,286,287,290,292,293,294,298,301,302,303],ev([229,255,276]))
scene('S10','十年前江家','功能：解释江辰复仇动机的闪回。\n结构：密室与书房由墙壁洞口/观察孔建立联系；少年江辰和江母在密室看书房。\n陈设：原文只明确隔墙洞口与两间空间，不预设书架暗门等机关。\n环境：第4集夜内，字幕“十年前”。',[237,238,239,240,241,242,243,244,245,247,248,249,250,251,252,253],ev([237],'闪回'))
scene('S10-01','书房','功能：黑袍人杀父与张阎王搜查。\n结构：密室中能经洞口看到书房；有容纳黑袍人、江父及搜查者的空间。\n陈设：具体家具未写，不能凭“书房”补成已确认的某种书柜布置。',[241,242,243,244,245,247,248],ev([242],'闪回'),'S10','子场景')
scene('S10-02','密室','功能：母亲保护少年江辰并留下临终嘱托。\n结构：有通向书房视线的墙壁洞口；可藏身，不等于原文给出了出入口机关。\n连续性：洞口高度、视线与书房中江父位置对应。',[241,248,249,250,251,252],ev([241],'闪回'),'S10','子场景')
scene('S11','张阎王家','功能：安排夜袭、接受血手援助。\n结构：第6集室内有沙发会客区，第9集明确别墅大厅与院中入厅路径；两室内区域是否同厅未说明。\n陈设：沙发、冷敷物；第9集有可摔碎的茶杯和站立的十名打手。',[306,307,308,309,312,418,419,420,422,424,425],ev([309,420]))
scene('S11-03','沙发会客区（第6集）','功能：冷敷面部并命令手下夜袭。\n结构／陈设：张阎王坐沙发，手下恭敬站着；毛巾和冰袋是人物护理物件。\n归并边界：是否即第9集大厅待确认，不能用同一家具摆法冒充原文。',[306,307,308,309,311,312,313,314,315],ev([309]),'S11','子场景')
scene('S11-01','别墅大厅（第9集）','功能：摔杯斥责、血手入厅立威与接任务。\n结构：可容十名打手围攻并倒地，院中可抵达大厅。\n陈设：茶杯是场景内交互物件，碎片位置应保持；其他家具未写。',[418,419,420,422,423,424,425,427,428,429,431],ev([420]),'S11','子场景')
scene('S11-01-01','茶杯破碎／立威结果','变化：茶杯被摔在地上、破碎一地；随后打手被血手击倒。\n连续性：碎片与人物倒地位置需承接，不让反打随意恢复完整杯。',[420,424,425,427],ev([420]),'S11-01','状态')
scene('S11-02','院中／入厅路径','功能：血手悄无声息进入并来到张阎王身前。\n结构：院子与大厅可连通；门型、朝向及是否需要独立院子全景未写。',[418,422],ev([422]),'S11','子场景')
scene('S02','大学校园','功能：上学接送、身份相认与发现布控。\n范围：第9集明确大学门口，第10集“学校”承接上一场；不因此扩增食堂、教学楼等未出现空间。\n结构：校门接送位置、豪车停靠与周围摆摊/清扫/接送人群关系需一致。',[433,434,435,436,437,441,445,452,453,456,457,460,462,468],ev([435,452]))
scene('S02-01','校门／接送区','功能：江辰护送、艾薇出现、两人察觉布控。\n结构：豪车能停靠，苏小菲从另一侧门下车；周围可见摆摊老头、清洁工、接送家长。\n连续性：第10集按剧情承接整合；具体校园建筑与距离没有写。',[433,435,436,438,441,445,446,449,452,456,457,460,462],ev([435,452]),'S02','子场景')
scene('S04','烂尾楼','功能：第10集引蛇出洞与血手击伤艾薇。\n范围：原文日外，实际写在烂尾楼下；本轮没有顶楼审问和室内战斗，不从60集清单提前加入。\n结构：楼下可容主角、反派与十名打手，具体建筑尺度、废料和柱网未描述。',[470,471,472,478,479,481,488,489,490,492,494,499,500],ev([472]))
scene('S04-01','楼下交战区','功能：艾薇挡护苏小菲、血手攻击、江辰画外音入场钩子。\n结构：两方可对峙、退三步与倒地，苏小菲可挡在艾薇前。\n陈设：未给具体器械、废料或破坏清单，不能凭“烂尾楼”视作原文明示道具。',[470,472,478,479,481,488,489,490,491,492,494,499,500],ev([472]),'S04','子场景')

used=set(oldprops.values());nextp=max(int(x[1:]) for x in used if x.startswith('P'))+1
def prop(name,desc,refs,events=None,oldname=None,key=None,parent='',kind='资产',candidate=False):
 global nextp
 if key is None:
  key=oldprops.get(oldname or name)
  if key is None:key=f'P{nextp:02}';nextp+=1
 return n('道具',key,name,desc,refs,events,parent,kind,candidate)
prop('西王母玉（阴玉见小传）','用途：绑架与追查的核心线索；小传称阴玉曾用于救治苏小菲。\n形态：本轮没有明确可见玉器的形制，也没有写它被取出。\n范围：按台词/心理/小传提及登记，不制作一枚凭空可随手摘取的玉佩；第8集“我有西……”属明确语境指代但未说完。',[19,23,28,66,75,104,105,111,124,125,127,234,244,260,312,377,408,409,410,411,475,495],ev([66,124,234,244,312,377,410,475],'仅提及'),oldname='西王母阴玉')
prop('孤狼银色半面具','用途：遮面与孤狼身份识别。\n外形／材质：半张银色面具；覆盖边界、扣带、材质未写。\n状态：第1集佩戴后摘下露出同一张脸；不从“银色”直接认定银金属。',[64,91,115],ev([64,115]))
prop('耳内通讯器','用途：江辰与老高联络。\n结构：位于耳朵里，具体左右耳、尺寸及外露结构未写。\n范围：第1集明确出现；不把其他集通电话都当作继续戴耳机。',[65,66,68],ev([65]),oldname='通讯耳机')
prop('绑缚绳索','用途：把苏小菲束在柱子上，后被江辰解开。\n外观／状态：勒紧并使衣物贴身，随后解缚；绳材、绳结、数量未写，不能改成割断而不说明。',[74,75,102],ev([74,102]))
prop('绑匪首领信号器','用途：向手下喊话，悬赏杀孤狼。\n结构：首领手持的信号器；具体无线电型号与按键未写。\n连续性：与江辰耳内通讯器是不同物件，不能共用成一只手机。',[95],ev([95]))
prop('棒棒糖','用途：苏小菲的日常习惯物件。\n出现：第2集含在嘴里，第3集拆开一根新糖，第9集再次叼糖。\n连续性：同类设计可复用，但不能把多次使用误认成全程同一根实物；颜色/包装未写。',[121,219,222,441],ev([121,219,441]))
phone=prop('手机〔按使用者分实物〕','分组用途：区分苏小菲的游戏手机与江辰的通话/信息手机，不能混同持有者。\n外形：均未提供机型与外壳细节；屏幕可读信息另列在江辰手机下。\n边界：第1集写江辰打通电话，但没有明确设备形态，不将其当成已写出的可见手机。',[110,111,121,126,374,376,438,439],ev([121,376,438]),oldname='普通手机')
prop('江辰手机','用途：第7集卧室通话后收起手机；第9集拿出手机看信息。\n外形：机型、壳色与尺寸未写。\n补充：第1集通话与本机是否同一实物尚无依据。',[110,111,374,375,376,438,439],ev([376,438]),key=phone['id']+'-01',parent=phone['id'])
prop('短信屏幕：血手来B市了。','可读内容：血手来B市了。\n用途：第9集提示追杀威胁到来。\n制作要求：保留原句、字母B和句号，不加清单里提到但本稿没有的IP或其他信息；界面样式未写。',[438,439,440],ev([439]),key=phone['id']+'-01-01',parent=phone['id']+'-01',kind='屏幕内容')
prop('苏小菲手机','用途：第2集在咖啡馆打游戏并退出游戏。\n外形与内容：机型和具体游戏未写，不擅用任何真实游戏画面作为原文。',[121,126],ev([121]),key=phone['id']+'-02',parent=phone['id'])
prop('主播拍摄装备','用途：女主播拍摄路人采访，镜头对准江辰。\n外形：原文只写拍摄装备，没有指定手机、相机或稳定器。\n连续性：第2集明确，第3集采访承接但未重述装备画面；后者不擅作已核出镜。',[159,175,180,181,193,195],ev([159,175]))
prop('寻找路人英雄广告牌','用途：门口采访的主题展示。\n文字：寻找路人英雄，原文明确。\n外形：女主播手持，尺寸、底色和版式未写；第3集是否仍入画未重述。',[159,160,161,162,172],ev([159]),oldname='寻找路人英雄广告牌')
prop('测谎仪','用途：验证采访回答。\n结构／状态：女主播给江辰戴上，第3集江辰拆下递回；指示器的具体外形未写。\n连续性：同一装置的佩戴、拆卸与回收对应，不擅自改成另一个测谎手环。',[162,169,170,190,195],ev([169,195]))
prop('无人机','用途：悬停、拍摄威慑；苏小菲称会上传视频。\n外形：型号与尺寸未写；第4—5集连续段同一叙事装置。\n归属：苏小菲称“我的无人机”；第9集江辰判断艾薇操控，这是人物判断，不补出已出现的遥控器。',[266,267,292,293,294,296,447],ev([266,292])+ev([447],'仅提及'))
prop('硬币','用途：江辰弹射击中张阎王小腿。\n数量／外形：第4集一块，币种、尺寸和正反面未写。\n边界：不能将第1集攻击光影自动认定为本硬币。',[267,268,269],ev([267]))
prop('脱落牙齿（两颗）','用途：第5集掌掴的慢镜头结果。\n数量：原文明写两颗；具体牙位未写。\n连续性：与张阎王受击状态关联，不把两颗脱落牙当作新增角色。',[286,287,290],ev([287]))
prop('毛巾','用途：包裹冰袋给张阎王冷敷红肿面部。\n外形：颜色、尺寸、材质未写；与冰袋是两个配合物件。',[309],ev([309]))
prop('冰袋','用途：第6集张阎王面部冷敷。\n状态：被毛巾包住；冰袋形状和包装形式未写。',[309],ev([309]))
prop('购物袋（十几个）','用途：江辰拎购物袋跟随苏小菲深夜归家并放下。\n数量：原文为十几个，不改写为精确十个。\n连续性：手持数量、两手分配及放下位置需按同一段保持，品牌和袋内商品未写。',[319,321],ev([319,321]))
prop('夜袭头领匕首','用途：第6集抽刀刺向江辰，第7集刀刃被双指夹住。\n数量／形态：一把，刀刃寒光；具体轮廓、材质与刀柄未写。\n连续性：相同刀身、握向、夹持位置承接，不混入第1集未明光影武器。',[340,348,350,355],ev([340,348,355]),oldname='匕首')
prop('直升机〔载具〕','用途：第1集接走苏小菲。\n外观／结构：盘旋落地后起飞，苏小菲坐在机内；机型、涂装及舱门方向未写。\n连续性：外部落点、乘员区与上下机动作对应，不补写未出镜驾驶员。',[108,109,110],ev([108]),key='T01',kind='载具')
prop('直升机乘员区域','用途：苏小菲坐在机内向江辰喊话。\n结构：需要对应同一架直升机的乘员座位和开口视线；座椅数量和内饰未写。',[108,109],ev([109]),key='T01-01',parent='T01',kind='载具子空间')
prop('保姆车〔载具〕','用途：第3集采访后离开。\n结构：江辰与苏小菲坐在对角位置，苏小菲能看向车外。\n外观：品牌、颜色、车型与车内座位总数未写。',[201,202,203,204],ev([201]),key='T02',kind='载具')
prop('保姆车对角座位／车窗区','结构：两人的座位呈对角关系，车窗是苏小菲避开视线时的观察方向。\n连续性：不要换车内朝向导致人物对角关系消失；具体座椅布局仍需设计。',[201,202,203,204],ev([202]),key='T02-01',parent='T02',kind='载具子空间')
prop('豪车〔载具〕','用途：第9集江辰驾车送苏小菲上学。\n结构：江辰与苏小菲从不同侧车门下车，停靠校门接送区域。\n外观：豪车级别已写，但品牌、颜色与车型未写；第10集是否留在画面不明确。',[435,436,441],ev([435,441]),key='T03',kind='载具')

